/* req-224 / req-226 / req-233: Estados e controle de densidade do Dashboard V3.0 (busca, SortableJS, P/M/G, capas 9rem/12rem, abas e widgets 12 cols min-h-220px). */
.dashboard-module-card.search-hidden { display: none !important; }
.dashboard-no-results { grid-column: 1 / -1; padding: 3em 1em; text-align: center; color: #64748b; }
.dashboard-card-svg { display: flex; }
.dashboard-card-svg svg { width: 100%; height: 100%; }
.sortable-ghost { opacity: .7; background: #f0f9ff !important; border: 2px dashed #0284c7 !important; }
.sortable-chosen { box-shadow: 0 12px 35px rgba(0,0,0,.18) !important; }
.sortable-drag { opacity: 1 !important; cursor: grabbing !important; }
.is-dragging, .is-dragging * { user-select: none !important; -webkit-user-select: none !important; }
.dashboard-card-drag-handle {
    user-select: none;
    -webkit-user-select: none;
    position: absolute;
    top: 0.625rem;
    left: 0.625rem;
    z-index: 20;
    background-color: rgba(255, 255, 255, 0.85);
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    box-shadow: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    border-radius: 0.375rem;
}
.dashboard-module-card.card-dropped { animation: c2f-dash-drop .3s ease-out; }
@keyframes c2f-dash-drop { from { transform: scale(.97); } to { transform: none; } }

/* Cover vs SVG Fallback (CA-4 / CA-5) */
.dashboard-module-card.has-cover .dashboard-card-svg { display: none !important; }
.dashboard-module-card.no-cover .dashboard-card-cover-wrapper { display: none !important; }
.dashboard-module-cover { width: 100% !important; height: calc(100% + 20px) !important; object-fit: cover !important; object-position: center -20px !important; display: block !important; }
#dashboard-sortable-cards.density-p .dashboard-card-drag-handle { display: none !important; }

/* Densidade P (Pequeno / Compacto) */
#dashboard-sortable-cards.density-p {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
}
@media (min-width: 768px) {
    #dashboard-sortable-cards.density-p { grid-template-columns: repeat(4, minmax(0, 1fr)); }
}
@media (min-width: 1024px) {
    #dashboard-sortable-cards.density-p { grid-template-columns: repeat(6, minmax(0, 1fr)); }
}
#dashboard-sortable-cards.density-p .dashboard-module-card {
    flex-direction: row;
    align-items: center;
    padding: 0.5rem 0.75rem;
    gap: 0.75rem;
}
#dashboard-sortable-cards.density-p .dashboard-card-header {
    height: 2.25rem;
    width: 2.25rem;
    min-width: 2.25rem;
    padding: 0;
    background: transparent;
    border-radius: 0.375rem;
}
#dashboard-sortable-cards.density-p .dashboard-card-svg {
    width: 1.5rem;
    height: 1.5rem;
}
#dashboard-sortable-cards.density-p .dashboard-card-cover-wrapper {
    width: 2.25rem;
    height: 2.25rem;
    border-radius: 0.375rem;
}
#dashboard-sortable-cards.density-p .dashboard-card-drag-handle { display: none; }
#dashboard-sortable-cards.density-p .dashboard-card-body { padding: 0; flex: 1; min-width: 0; }
#dashboard-sortable-cards.density-p .dashboard-card-title {
    font-size: 0.875rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
#dashboard-sortable-cards.density-p .dashboard-card-meta,
#dashboard-sortable-cards.density-p .dashboard-card-description,
#dashboard-sortable-cards.density-p .dashboard-card-actions {
    display: none !important;
}

/* Densidade M (Médio / Padrão - req-233 CA-4: 9rem / 144px) */
#dashboard-sortable-cards.density-m .dashboard-card-header {
    height: 13.2rem !important;
}
#dashboard-sortable-cards.density-m .dashboard-card-svg {
    width: 4rem;
    height: 4rem;
}
#dashboard-sortable-cards.density-m .dashboard-card-shortcut {
    display: none !important;
}

/* Densidade G (Grande / Operacional - req-233 CA-4: 12rem / 192px) */
#dashboard-sortable-cards.density-g {
    grid-template-columns: repeat(1, minmax(0, 1fr));
    gap: 1.5rem;
}
@media (min-width: 1024px) {
    #dashboard-sortable-cards.density-g {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
#dashboard-sortable-cards.density-g .dashboard-card-header {
    height: 17.5rem !important;
}
#dashboard-sortable-cards.density-g .dashboard-card-svg {
    width: 5.5rem;
    height: 5.5rem;
}
#dashboard-sortable-cards.density-g .dashboard-card-description {
    -webkit-line-clamp: unset !important;
    display: block !important;
}
#dashboard-sortable-cards.density-g .dashboard-card-shortcut {
    display: block !important;
}

/* Abas */
.dashboard-tab-trigger.active {
    border-bottom-color: #0284c7 !important;
    color: #0284c7 !important;
}
.dashboard-tab-panel.hidden {
    display: none !important;
}

/* Widgets Grid (req-233 CA-1 & CA-2: Malha canônica de 12 colunas, min-h-[220px]) */
#dashboard-widgets-grid {
    display: grid;
    grid-template-columns: repeat(1, minmax(0, 1fr));
    gap: 1.5rem;
}
@media (min-width: 640px) {
    #dashboard-widgets-grid {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
@media (min-width: 1024px) {
    #dashboard-widgets-grid {
        grid-template-columns: repeat(12, minmax(0, 1fr));
    }
}

/* Lousa (REQ-248): colunas que acompanham a largura (`--board-cols`, calculado no JS), linhas de 20 px e
   a mesma distância de 20 px entre os cards. Cada card recebe coluna e linha no próprio estilo. */
#dashboard-widgets-grid.is-board {
    grid-template-columns: repeat(var(--board-cols, 12), minmax(0, 1fr));
    grid-auto-rows: 20px;
    gap: 0 20px;
    align-items: start;
    min-height: 240px;
}

.dashboard-widget-card {
