/* Modificadores de coluna da grade (Desktop 12 cols, Tablet 6 cols, Mobile 1 col). REQ-247: de 2 a 12, uma a uma.
   Na lousa a coluna e a extensão vão no estilo do próprio card e prevalecem. */
.dashboard-widget-card[data-widget-cols="2"] {
    grid-column: span 1 / span 1;
}
.dashboard-widget-card[data-widget-cols="3"] {
    grid-column: span 1 / span 1;
}
