}

.module-back-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 10px 16px;
    border: none;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
    cursor: pointer;
    font-size: 14px;
    transition: all 0.2s ease;
}

.module-back-btn:hover {
    background: rgba(255, 255, 255, 0.2);
}

.module-back-btn svg {
    width: 18px;
    height: 18px;
}

.module-header h3 {
    flex: 1;
    margin: 0;
    font-size: 16px;
    color: #fff;
}

.module-expand-btn {
    width: 40px;
    height: 40px;
    border: none;
    border-radius: 8px;
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.module-expand-btn:hover {
    background: rgba(74, 158, 255, 0.3);
}

.module-expand-btn svg {
