}

.dashboard-widget-card.is-resizing {
    outline: 2px solid #0284c7 !important;
    user-select: none !important;
    -webkit-user-select: none !important;
    z-index: 20;
}

/* Alça de redimensionamento no canto inferior direito */
.dashboard-widget-resize-handle {
    position: absolute;
    bottom: 4px;
    right: 4px;
    width: 22px;
    height: 22px;
    cursor: nwse-resize;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #94a3b8;
    background: transparent;
    border: none;
    padding: 0;
    border-radius: 4px;
    z-index: 10;
