.dashboard-widget-resize-handle:hover,
.dashboard-widget-card.is-resizing .dashboard-widget-resize-handle {
    color: #0284c7;
    background-color: rgba(2, 132, 199, 0.12);
}

/* Dropdown popover de troca rápida de widget */
.dashboard-widget-switch-menu {
    position: absolute;
    top: 100%;
    right: 0;
    z-index: 30;
    margin-top: 0.25rem;
