}
.dashboard-widget-switch-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    width: 100%;
    padding: 0.5rem 0.75rem;
    border-radius: 0.5rem;
    font-size: 0.8125rem;
    font-weight: 500;
    color: #334155;
    text-align: left;
    transition: background-color 0.15s ease;
}
.dashboard-widget-switch-item:hover {
    background-color: #f1f5f9;
    color: #0284c7;
}
.dashboard-widget-switch-item.active {
    background-color: #f0f9ff;
    color: #0284c7;
    font-weight: 600;
}

/* req-236: tooltip stays above adjacent cards and expands into the cover. */
.dashboard-module-card:has(.dashboard-card-drag-handle:hover),
.dashboard-module-card:has(.dashboard-card-drag-handle:focus-visible) { position: relative; z-index: 100030; }
.dashboard-card-drag-handle::after { left: 0 !important; right: auto !important; transform: none !important; min-width: max-content; z-index: 100030 !important; }
.dashboard-module-card.has-cover .dashboard-card-svg { display: none !important; }
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-drag-handle,
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-resize-handle,
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-switch-btn,
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-remove-btn { display: none !important; }
.dashboard-options-menu { max-width: calc(100vw - 2rem); }
.dashboard-widget-card-body { display: flex; min-height: 0; }
.dashboard-widget-frame { width: 100%; height: 100%; min-height: 150px; border: 0; flex: 1; }

/* REQ-238: a background blueprint never enters Sortable's child list. */
#dashboard-widgets-grid { position: relative; isolation: isolate; }
#dashboard-widgets-grid::before { content: ''; position: absolute; inset: -8px; pointer-events: none; z-index: -1; opacity: 0; border-radius: 12px; background-image: radial-gradient(#7dd3fc 1px, transparent 1px), repeating-linear-gradient(to right, transparent 0, transparent calc(100% / 12 - 1px), #bae6fd calc(100% / 12 - 1px), #bae6fd calc(100% / 12)); background-size: 12px 60px, 100% 100%; transition: opacity .2s ease; }
#dashboard-widgets-grid.is-interacting::before { opacity: .7; }
.dashboard-widget-card { min-width: 0; overflow: hidden; }
.dashboard-widget-card.is-resizing iframe { pointer-events: none; }
.dashboard-widget-frame { min-height: 0; }
#dashboard-widgets-modal [data-widget-choice] { justify-content: flex-start; text-align: left; }
#dashboard-widgets-modal [data-widget-choice][aria-pressed="true"] { border-color: #0284c7; background: #f0f9ff; color: #0284c7; }
#dashboard-widgets-modal [data-widget-choice][hidden] { display: none; }
#dashboard-edit-mode { display: flex; justify-content: space-between; gap: 1rem; }
.dashboard-edit-track { display: inline-flex; align-items: center; flex-shrink: 0; width: 2.5rem; height: 1.4rem; padding: 3px; border-radius: 999px; background: #cbd5e1; transition: background .2s; }
.dashboard-edit-thumb { width: 1rem; height: 1rem; background: white; border-radius: 50%; transition: transform .2s; }
#dashboard-edit-mode[aria-checked="true"] .dashboard-edit-track { background: #0284c7; }
#dashboard-edit-mode[aria-checked="true"] .dashboard-edit-thumb { transform: translateX(1.1rem); }

/* REQ-239: contexto legível no compacto e enquadramento da capa operacional. */
#dashboard-sortable-cards.density-p .dashboard-card-header { width: 2.25rem !important; flex: 0 0 2.25rem; }
#dashboard-sortable-cards.density-p .dashboard-module-card { background: #f8fafccc; }
#dashboard-sortable-cards.density-p .dashboard-card-cover-wrapper { display: none !important; }
#dashboard-sortable-cards.density-p .dashboard-card-svg { display: flex !important; }
#dashboard-sortable-cards.density-p .dashboard-card-svg svg { width: 1.5rem; height: 1.5rem; }
#dashboard-sortable-cards.density-p .dashboard-card-title { font-size: .75rem; font-weight: 600; color: #1e293b; }
#dashboard-sortable-cards.density-g .dashboard-module-cover { height: 100% !important; object-position: center 15% !important; }

/* REQ-242: abas com os mesmos estados de repouso, hover, foco e ativa (a marcação das duas é igual). */
.dashboard-tab-trigger { border-bottom: 2px solid transparent; color: #64748b; font-weight: 600; transition: color .15s ease, border-color .15s ease; }
.dashboard-tab-trigger:hover:not(.active) { border-bottom-color: #cbd5e1; color: #334155; }
.dashboard-tab-trigger:focus-visible { outline: 2px solid #0284c7; outline-offset: 2px; border-radius: 4px 4px 0 0; }
.dashboard-tab-trigger.active { border-bottom-color: #0284c7 !important; color: #0284c7 !important; }

/* REQ-242: capa OU ícone, nunca os dois. Sem capa (ou com a imagem falhando) fica só o ícone centralizado. */
.dashboard-module-card.has-cover .dashboard-card-svg { display: none !important; }
.dashboard-module-card.no-cover .dashboard-card-cover-wrapper { display: none !important; }
.dashboard-module-card.no-cover .dashboard-card-svg { display: flex !important; }
.dashboard-module-card.no-cover .dashboard-card-svg svg { width: 4rem; height: 4rem; }
#dashboard-sortable-cards.density-g .dashboard-module-card.no-cover .dashboard-card-svg svg { width: 5.5rem; height: 5.5rem; }
#dashboard-sortable-cards.density-p .dashboard-module-card .dashboard-card-svg { display: flex !important; }
#dashboard-sortable-cards.density-p .dashboard-module-card .dashboard-card-svg svg { width: 1.5rem; height: 1.5rem; }

/* REQ-242: menu de opções em linhas, no padrão dos menus do painel. */
.dashboard-menu-item { display: flex; width: 100%; align-items: center; gap: .5rem; border-radius: .375rem; padding: .5rem; color: #334155; font-size: .75rem; font-weight: 500; line-height: 1rem; text-align: left; cursor: pointer; transition: background-color .15s ease, color .15s ease; }
.dashboard-menu-item:hover { background: #f1f5f9; color: #0f172a; }
.dashboard-menu-item:focus-visible { outline: 2px solid #0284c7; outline-offset: -2px; }
.dashboard-menu-item svg { width: 1rem; height: 1rem; flex-shrink: 0; color: #64748b; }
#dashboard-edit-mode { justify-content: flex-start; gap: .5rem; }
#dashboard-edit-mode[aria-checked="true"] { color: #0369a1; }
.dashboard-edit-track { width: 2rem; height: 1.125rem; padding: 2px; }
.dashboard-edit-thumb { width: .875rem; height: .875rem; }
#dashboard-edit-mode[aria-checked="true"] .dashboard-edit-thumb { transform: translateX(.875rem); }
.dashboard-widget-card-header .c2fc-botao-icone { padding: 5px; box-shadow: none; }

/* REQ-242: malha técnica pontilhada (20 px, o passo vertical do redimensionamento) no lugar das linhas de coluna;
   widgets compactos descem até 120 px. */
#dashboard-widgets-grid::before {
    inset: -8px -8px -140px -8px;
    background-color: rgba(240, 249, 255, .55);
    background-image: radial-gradient(circle at 1px 1px, rgba(14, 165, 233, .5) 1px, transparent 1.5px), linear-gradient(rgba(14, 165, 233, .07) 1px, transparent 1px), linear-gradient(90deg, rgba(14, 165, 233, .07) 1px, transparent 1px);
    background-size: 20px 20px, 20px 20px, 20px 20px;
    background-position: 8px 8px;
}
#dashboard-widgets-grid.is-interacting::before { opacity: 1; }
.dashboard-widget-card, .dashboard-widget-card.h-1x, .dashboard-widget-card[data-widget-height="1"] { min-height: 120px; }
.dashboard-widget-card.is-resizing { box-shadow: 0 10px 25px -8px rgba(2, 132, 199, .45); }
.dashboard-widget-card.is-resizing::after { content: attr(data-resize-size); position: absolute; right: 30px; bottom: 6px; z-index: 11; border-radius: 6px; background: #0f172a; padding: 2px 6px; color: #f8fafc; font: 600 11px/1.3 system-ui, sans-serif; pointer-events: none; }
.dashboard-widget-card-body { padding: 0; }
.dashboard-widget-card-body:not(:has(> iframe)) { padding: 1rem; }

/* REQ-244: o iframe preenche somente a área útil do card. */
.dashboard-widget-card-header { flex-shrink: 0; }
.dashboard-widget-card-body { flex: 1; width: 100%; min-height: 0; padding: 0; overflow: hidden; position: relative; }
.dashboard-widget-frame { display: block; width: 100%; height: 100%; border: 0; min-height: 0; }

/* Configurações por widget: cabeçalho, moldura, cor de fundo e margem interna. */
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-config-btn { display: none !important; }
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-card.is-headerless .dashboard-widget-card-header { display: none; }
#dashboard-widgets-grid.is-editing .dashboard-widget-card.is-headerless .dashboard-widget-card-header { border-bottom-style: dashed; border-bottom-color: #94a3b8; }
.dashboard-widget-card.is-frameless { border-color: transparent; box-shadow: none; }
#dashboard-widgets-grid.is-editing .dashboard-widget-card.is-frameless { border-color: #94a3b8; border-style: dashed; }
.dashboard-widget-card .dashboard-widget-card-body[data-widget-padding="small"] { padding: 8px; }
.dashboard-widget-card .dashboard-widget-card-body[data-widget-padding="medium"] { padding: 16px; }
.dashboard-widget-card .dashboard-widget-card-body[data-widget-padding="large"] { padding: 24px; }
.dashboard-widget-card[data-widget-tone="dark"] .dashboard-widget-card-header { border-bottom-color: rgb(255 255 255 / 0.18); color: #f8fafc; }
.dashboard-widget-card[data-widget-tone="dark"] .dashboard-widget-card-header .c2fc-botao-fantasma { color: #e2e8f0; }
.dashboard-widget-card[data-widget-tone="dark"] .dashboard-widget-card-header .c2fc-botao-fantasma:hover { background: rgb(255 255 255 / 0.12); }
.dashboard-widget-config-color { width: 44px; height: 32px; padding: 2px; border: 1px solid #cbd5e1; border-radius: 8px; background: #fff; cursor: pointer; }
.dashboard-widget-config-color:disabled { opacity: 0.4; cursor: not-allowed; }
.dashboard-widget-config-switch { border: 1px solid #e2e8f0; font-size: .875rem; line-height: 1.25rem; }
.dashboard-widget-config-switch input:checked + .dashboard-edit-track { background: #0284c7; }
.dashboard-widget-config-switch input:checked + .dashboard-edit-track .dashboard-edit-thumb { transform: translateX(.875rem); }
.dashboard-widget-config-switch:has(input:focus-visible) { outline: 2px solid #0284c7; outline-offset: -2px; }

/* REQ-247: ferramentas do card, fonte do layout, tela cheia e pop-up de layouts. */
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-duplicate-btn,
#dashboard-widgets-grid:not(.is-editing) .dashboard-widget-edit-btn { display: none !important; }
.dashboard-widget-edit-btn[hidden] { display: none !important; }
#dashboard-widgets-grid.is-editing .dashboard-widget-card-header { flex-wrap: wrap; row-gap: 2px; }
#dashboard-widgets-grid.is-editing .dashboard-widget-title { min-width: 3rem; }
#dashboard-widgets-source[aria-checked="true"] .dashboard-edit-track { background: #0284c7; }
#dashboard-widgets-source[aria-checked="true"] .dashboard-edit-thumb { transform: translateX(.875rem); }
.dashboard-menu-item:disabled { opacity: .45; cursor: not-allowed; }
.dashboard-menu-item:disabled:hover { background: transparent; color: #334155; }
.dashboard-layout-row { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; border: 1px solid #e2e8f0; border-radius: 8px; padding: 8px 12px; }
.dashboard-layout-name { min-width: 0; flex: 1 1 8rem; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: .875rem; font-weight: 600; color: #0f172a; }
.dashboard-layout-detail { font-size: .75rem; color: #64748b; }
.dashboard-layout-row .c2fc-botao { padding: 4px 10px; font-size: .75rem; }
.dashboard-layout-check { width: 16px; height: 16px; flex: none; accent-color: #0284c7; }
.dashboard-layout-empty { font-size: .8125rem; color: #64748b; }

/* REQ-248: arrasto livre na lousa, janela cheia e opções flutuantes. */
#dashboard-widgets-grid.is-board .dashboard-widget-card { align-self: start; }
.dashboard-widget-card.is-dragging { z-index: 30; opacity: .92; box-shadow: 0 18px 40px rgb(15 23 42 / 0.28); cursor: grabbing; transition: none; }
.dashboard-widget-card.is-dragging iframe { pointer-events: none; }
#dashboard-widgets-grid.is-interacting iframe { pointer-events: none; }
.dashboard-board-ghost { align-self: stretch; margin-bottom: 20px; border: 2px dashed #0ea5e9; border-radius: 12px; background: rgb(14 165 233 / 0.10); pointer-events: none; }
#dashboard-tab-widgets.is-window { position: fixed; inset: 0; z-index: 45; margin: 0; overflow: auto; background: #f1f5f9; padding: 16px 16px 88px; }
html.dashboard-window-open { overflow: hidden; }
#dashboard-btn-widgets-window[aria-checked="true"] .dashboard-edit-track, #dashboard-widgets-mode[aria-checked="true"] .dashboard-edit-track, #dashboard-widgets-first[aria-checked="true"] .dashboard-edit-track { background: #0284c7; }
#dashboard-btn-widgets-window[aria-checked="true"] .dashboard-edit-thumb, #dashboard-widgets-mode[aria-checked="true"] .dashboard-edit-thumb, #dashboard-widgets-first[aria-checked="true"] .dashboard-edit-thumb { transform: translateX(.875rem); }
#dashboard-options { position: fixed; right: 16px; bottom: 16px; z-index: 46; }
#dashboard-options > summary { border-radius: 999px; padding: 10px 16px; box-shadow: 0 10px 25px rgb(15 23 42 / 0.22); list-style: none; }
#dashboard-options > summary::-webkit-details-marker { display: none; }
#dashboard-options[open] > summary { border-color: #0284c7; color: #0369a1; }
#dashboard-options .dashboard-options-menu { top: auto; right: 0; bottom: calc(100% + 8px); margin: 0; max-height: calc(100vh - 96px); overflow-y: auto; box-shadow: 0 18px 40px rgb(15 23 42 / 0.22); }
.dashboard-per-row { display: flex; align-items: center; gap: 4px; padding: .375rem .5rem; color: #334155; font-size: .75rem; font-weight: 500; }
.dashboard-per-row-label { min-width: 0; flex: 1; }
.dashboard-per-row button { width: 1.625rem; height: 1.625rem; border: 1px solid #cbd5e1; border-radius: .375rem; background: #fff; font-weight: 600; color: #334155; cursor: pointer; }
.dashboard-per-row button:hover:not(:disabled) { border-color: #0284c7; color: #0369a1; }
.dashboard-per-row button:disabled { opacity: .4; cursor: not-allowed; }

/* REQ-250: objetos livres, esconder por largura, imagem de fundo e pop-up de configurações mais longo. */
.dashboard-widget-card.is-hidden-now { display: none !important; }
#dashboard-widgets-grid.is-editing .dashboard-widget-card[data-widget-hide] { outline: 2px dashed #f59e0b; outline-offset: -2px; }
.dashboard-widget-card.has-bg-image::before { content: ""; position: absolute; inset: 0; z-index: 0; border-radius: inherit; background-image: var(--widget-bg-image); background-position: center; background-size: var(--widget-bg-size, cover); background-repeat: var(--widget-bg-repeat, no-repeat); opacity: var(--widget-bg-opacity, 1); pointer-events: none; }
.dashboard-widget-card.has-bg-image > .dashboard-widget-card-header, .dashboard-widget-card.has-bg-image > .dashboard-widget-card-body { position: relative; z-index: 1; }
.dashboard-widget-card.is-object .dashboard-widget-switch-btn, .dashboard-widget-card.is-object .dashboard-widget-edit-btn { display: none !important; }
.dashboard-widget-card.is-object { min-height: 0; }
.dashboard-object { display: flex; width: 100%; height: 100%; min-height: 0; align-items: center; justify-content: center; overflow: hidden; }
.dashboard-object.is-placeholder { color: #94a3b8 !important; font-size: .875rem !important; font-weight: 500 !important; font-style: italic; }
.dashboard-object-text { display: block; align-content: center; padding: 8px 12px; line-height: 1.2; white-space: pre-wrap; overflow-wrap: anywhere; }
.dashboard-object-figure { width: 100%; height: 100%; }
.dashboard-object-figure[data-shape="rounded"] { border-radius: 16px; }
.dashboard-object-figure[data-shape="circle"] { border-radius: 50%; }
.dashboard-object-figure[data-shape="line"] { height: 4px; border-radius: 2px; }
.dashboard-object-image img { width: 100%; height: 100%; display: block; }
.dashboard-object-icon svg { width: min(100%, 100cqh); height: 100%; max-height: 100%; }
.dashboard-object-icon { padding: 8%; }
.dashboard-object-action { display: inline-flex; max-width: 100%; align-items: center; justify-content: center; border-radius: 999px; padding: .6em 1.4em; text-align: center; text-decoration: none; line-height: 1.1; box-shadow: 0 6px 18px rgb(15 23 42 / 0.18); }
.dashboard-object-action:hover { filter: brightness(1.08); }
#dashboard-widgets-grid.is-editing .dashboard-object-action { pointer-events: none; }
#dashboard-widget-config-modal > div { display: flex; max-height: calc(100vh - 32px); flex-direction: column; }
#dashboard-widget-config-modal > div > .space-y-4 { min-height: 0; overflow-y: auto; }
#dashboard-widget-config-modal [hidden] { display: none !important; }
/* O seletor de imagem abre por cima do pop-up de configurações, que está na mesma camada dos outros pop-ups. */
#dashboard-image-picker { z-index: 60; }
